// Compare the same Python read against Docker CLI and its local Engine API.
// Uses synthetic fixtures generated by probe-microsandbox.mjs. Pull the image first.
import { readFile, writeFile, realpath } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import { tmpdir } from 'node:os';
import http from 'node:http';
import { docker } from '../lib/docker-executor.js';

const run = await realpath(process.argv[2]);
const relative = path.relative(await realpath(tmpdir()), run);
if (!relative || path.isAbsolute(relative) || relative.startsWith('..')) throw new Error('Expected temp lab fixture directory');
const original = JSON.parse(await readFile(path.join(run, 'results.json'), 'utf8'));
const source = path.join(run, 'public'), work = path.join(run, 'private/alice');
const image = original.image;
const code = 'from pathlib import Path; assert Path("/public/read.txt").read_text() == "PUBLIC_FIXTURE"; print("ok")';
const result = { startedAt: new Date().toISOString(), image, workload: code,
  policy: { cpus: 1, memoryMiB: 512, rootFilesystem: 'read-only', user: '0:0', network: 'none', caps: 'none' }, performance: {}, errors: [], cleanup: [] };
const live = new Set();
function stats(values) {
  const s = [...values].sort((a,b)=>a-b), round = n=>Math.round(n*100)/100;
  return {count:s.length,minMs:round(s[0]),medianMs:round((s[Math.floor((s.length-1)/2)]+s[Math.floor(s.length/2)])/2),maxMs:round(s.at(-1)),samplesMs:values.map(round)};
}
async function create() {
  const name = 'a2a-msb-docker-compare-' + randomUUID();
  live.add(name);
  const t = performance.now();
  await docker(['run','-d','--pull=never','--name',name,'--label','talk2myagent.probe=microsandbox',
    '--network=none','--read-only','--user=0:0','--cap-drop=ALL','--security-opt=no-new-privileges',
    '--pids-limit=64','--memory=512m','--cpus=1','--tmpfs=/tmp:rw,nosuid,nodev,noexec,size=67108864',
    '--mount',`type=bind,src=${source},dst=/public,readonly,bind-recursive=disabled`,
    '--mount',`type=bind,src=${work},dst=/work,bind-recursive=disabled`, image,'sleep','600'], '', undefined, 60000);
  return { name, ms: performance.now()-t };
}
async function remove(name) { await docker(['rm','-f',name]); live.delete(name); result.cleanup.push(name); }
async function command(name) { const out = await docker(['exec',name,'python3','-c',code]); if(out.trim()!=='ok') throw new Error('Unexpected guest output'); }
try {
  const ctx = JSON.parse(await docker(['context','inspect']))[0];
  const endpoint = ctx.Endpoints.docker.Host;
  const match = /^npipe:\/+\.\/pipe\/(.+)$/.exec(endpoint);
  if (!match) throw new Error('This experiment requires a local Windows named pipe Docker endpoint');
  const socketPath = '\\\\.\\pipe\\' + match[1];
  function request(method, route, payload) {
    return new Promise((resolve,reject)=>{
      const body = payload === undefined ? null : JSON.stringify(payload);
      const req = http.request({ socketPath, method, path: route,
        headers: body === null ? {} : {'Content-Type':'application/json','Content-Length':Buffer.byteLength(body)} },res=>{
        const chunks=[]; res.on('data',c=>chunks.push(c));res.on('error',reject);res.on('end',()=>{
          const bytes=Buffer.concat(chunks);
          if(res.statusCode>=300) reject(new Error(`Docker API ${res.statusCode}: ${bytes}`)); else resolve(bytes);
        });
      }); req.setTimeout(30000,()=>req.destroy(new Error('Docker API timeout')));req.on('error',reject);req.end(body);
    });
  }
  async function apiCommand(name) {
    const created=JSON.parse(await request('POST',`/containers/${name}/exec`,{ AttachStdout:true,AttachStderr:true,Cmd:['python3','-c',code] }));
    const output=await request('POST',`/exec/${created.Id}/start`,{Detach:false,Tty:false});
    const status=JSON.parse(await request('GET',`/exec/${created.Id}/json`));
    if(status.ExitCode!==0 || !output.includes(Buffer.from('ok\n'))) throw new Error('Docker API command failed');
  }
  result.engineVersion = JSON.parse(await request('GET','/version')).Version;
  result.imageInspect = JSON.parse(await docker(['image','inspect',image,'--format','{{json .RepoDigests}}']));
  console.log('Docker cached create and first Python read (10 samples)');
  const creates=[],reads=[],destroys=[];
  for(let i=0;i<10;i++) {
    const {name,ms}=await create(); creates.push(ms);
    try {const t=performance.now();await command(name);reads.push(ms+performance.now()-t);}
    finally{const t=performance.now();await remove(name);destroys.push(performance.now()-t);}
  }
  result.performance.cachedCreateCli=stats(creates);result.performance.cachedCreateAndPythonReadCli=stats(reads);result.performance.destroyCli=stats(destroys);
  const {name}=await create();
  try {
    await command(name);
    result.python=await docker(['exec',name,'python3','--version']);
    const cli=[],api=[];
    console.log('Docker reuse: CLI then direct Engine API (20 samples each)');
    for(let i=0;i<20;i++){const t=performance.now();await command(name);cli.push(performance.now()-t);}
    for(let i=0;i<20;i++){const t=performance.now();await apiCommand(name);api.push(performance.now()-t);}
    result.performance.execPythonReadCli=stats(cli);result.performance.execPythonReadEngineApi=stats(api);
  } finally {await remove(name);}
} catch(error){result.errors.push(String(error));process.exitCode=1;}
finally {
  for(const name of live) await remove(name).catch(error=>result.errors.push(String(error)));
  result.finishedAt=new Date().toISOString();
  await writeFile(path.join(run,'docker-baseline.json'),JSON.stringify(result,null,2));
  console.log(JSON.stringify(result,null,2));
}
